WITH frame_r AS MATERIALIZED (SELECT frame_r__t0.*
  FROM T AS frame_r__t0), __e_0 AS (SELECT CAST(CASE WHEN regexp_full_match(CAST(value AS VARCHAR), '-?0+(\.0+)?') THEN '0.0' WHEN strpos(CAST(value AS VARCHAR), 'e') > 0 OR strpos(CAST(value AS VARCHAR), 'E') > 0 THEN concat(CASE WHEN starts_with(CAST(value AS VARCHAR), '-') THEN '-' ELSE '' END, CASE WHEN CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) <= 0 THEN concat('0.', rpad('', CAST(CAST(greatest(0 - (CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER)), 0) AS INTEGER) AS INTEGER), '0'), replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '')) WHEN CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) >= length(CAST(replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '') AS VARCHAR)) THEN concat(replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), rpad('', CAST(CAST(greatest(CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) - length(CAST(replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '') AS VARCHAR)), 0) AS INTEGER) AS INTEGER), '0'), '.0') ELSE concat(substr(replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), 1, CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER)), '.', substr(replace(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), greatest(CASE WHEN strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(value AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(value AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) + 1, 1))) END) WHEN NOT strpos(CAST(value AS VARCHAR), '.') > 0 THEN concat(CAST(value AS VARCHAR), '.0') ELSE CAST(value AS VARCHAR) END AS VARCHAR) AS __c, ROW_NUMBER() OVER () AS __rn, CAST(value AS DOUBLE) AS __v
  FROM (
    SELECT UNNEST(list_filter([CAST(0.5 AS DOUBLE), CAST(1.5 AS DOUBLE), CAST(2.5 AS DOUBLE)], x -> x IS NOT NULL)) AS value
  ) AS side
  WHERE value IS NOT NULL), __a_0 AS (SELECT CAST(CASE WHEN regexp_full_match(CAST(u_map__amount AS VARCHAR), '-?0+(\.0+)?') THEN '0.0' WHEN strpos(CAST(u_map__amount AS VARCHAR), 'e') > 0 OR strpos(CAST(u_map__amount AS VARCHAR), 'E') > 0 THEN concat(CASE WHEN starts_with(CAST(u_map__amount AS VARCHAR), '-') THEN '-' ELSE '' END, CASE WHEN CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) <= 0 THEN concat('0.', rpad('', CAST(CAST(greatest(0 - (CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER)), 0) AS INTEGER) AS INTEGER), '0'), replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '')) WHEN CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) >= length(CAST(replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '') AS VARCHAR)) THEN concat(replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), rpad('', CAST(CAST(greatest(CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) - length(CAST(replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', '') AS VARCHAR)), 0) AS INTEGER) AS INTEGER), '0'), '.0') ELSE concat(substr(replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), 1, CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER)), '.', substr(replace(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.', ''), greatest(CASE WHEN strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') = 0 THEN length(CAST(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS VARCHAR)) ELSE strpos(regexp_extract(CAST(u_map__amount AS VARCHAR), '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1), '.') - 1 END + CAST(CASE WHEN regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(CAST(u_map__amount AS VARCHAR), '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) + 1, 1))) END) WHEN NOT strpos(CAST(u_map__amount AS VARCHAR), '.') > 0 THEN concat(CAST(u_map__amount AS VARCHAR), '.0') ELSE CAST(u_map__amount AS VARCHAR) END AS VARCHAR) AS __c, ROW_NUMBER() OVER () AS __rn, CAST(u_map__amount AS DOUBLE) AS __v
  FROM (
    SELECT frame_r_t0.AMOUNT AS u_map__amount
    FROM frame_r AS frame_r_t0
    WHERE frame_r_t0.AMOUNT IS NOT NULL
  ) AS side
  WHERE u_map__amount IS NOT NULL), __se_0 AS (SELECT CASE WHEN s.__n = 0 THEN '[]' WHEN s.__n = 1 THEN s.__one ELSE concat('[', s.__joined, ']') END AS __text, s.__nulls AS __nulls, s.__trees AS __trees, s.__n AS __n
  FROM (
    SELECT COUNT(__e.__rn) AS __n, MIN(CASE WHEN __e.__rn = 1 THEN __e.__c END) AS __one, STRING_AGG(__e.__c, ', ' ORDER BY __e.__c ASC) AS __joined, COUNT(CASE WHEN __e.__c IS NULL THEN 1 END) AS __nulls, COUNT(CASE WHEN strpos(__e.__c, 'tree') > 0 THEN 1 END) AS __trees
    FROM __e_0 AS __e
  ) AS s), __sa_0 AS (SELECT CASE WHEN s.__n = 0 THEN '[]' WHEN s.__n = 1 THEN s.__one ELSE concat('[', s.__joined, ']') END AS __text, s.__nulls AS __nulls, s.__trees AS __trees, s.__n AS __n
  FROM (
    SELECT COUNT(__a.__rn) AS __n, MIN(CASE WHEN __a.__rn = 1 THEN __a.__c END) AS __one, STRING_AGG(__a.__c, ', ' ORDER BY __a.__c ASC) AS __joined, COUNT(CASE WHEN __a.__c IS NULL THEN 1 END) AS __nulls, COUNT(CASE WHEN strpos(__a.__c, 'tree') > 0 THEN 1 END) AS __trees
    FROM __a_0 AS __a
  ) AS s), __sl_0 AS (SELECT 0 AS __ne, 0 AS __na, COUNT(CASE WHEN NOT ((__e.__c IS NOT DISTINCT FROM __a.__c) OR __e.__v IS NOT NULL AND __a.__v IS NOT NULL AND abs(__e.__v) <= 1.7976931348623157E308 AND abs(__a.__v) <= 1.7976931348623157E308 AND abs(__e.__v - __a.__v) <= CASE WHEN greatest(abs(__e.__v), abs(__a.__v)) = CAST(0.0 AS DOUBLE) THEN CAST(0.0 AS DOUBLE) ELSE CAST(2.0 AS DOUBLE) * power(CAST(2.0 AS DOUBLE), CAST(floor((CAST(ln(greatest(abs(__e.__v), abs(__a.__v))) AS DOUBLE) / CAST(ln(CAST(2.0 AS DOUBLE)) AS DOUBLE))) AS BIGINT) - 52) END) THEN 1 END) AS __bad
  FROM __e_0 AS __e
  JOIN __a_0 AS __a ON __e.__rn = __a.__rn)
SELECT 0 AS __ix, (e.__text IS NOT DISTINCT FROM a.__text) OR e.__n = a.__n AND l.__bad = 0 AS __verdict, e.__text AS __expected, a.__text AS __actual, CASE WHEN e.__nulls > 0 OR a.__nulls > 0 THEN 'null-canon-cell' WHEN e.__trees > 0 OR a.__trees > 0 THEN 'unclaimable tree cell' END AS __unjudged, NOT (e.__text IS NOT DISTINCT FROM a.__text) AND e.__n = a.__n AND l.__bad = 0 AS __lenient
FROM __se_0 AS e
CROSS JOIN __sa_0 AS a
CROSS JOIN __sl_0 AS l
